-- REVIEW ONLY: explicit approval required to renew sensitive private-data access.
-- Same reader/credentials/grants; renew role, bounded ACK and Auth view until Nov 12.
-- No application rows, Auth credentials, policies or capture triggers are changed.
BEGIN;
SET LOCAL timezone='UTC';
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
DO $renew$
DECLARE definition text; body text; before_acl aclitem[]; view_acl aclitem[];
BEGIN
 IF '__APPROVE_CAPTURE_RENEWAL_20261105__' <> 'approved-capture-renewal-v1' THEN RAISE EXCEPTION 'Review-only renewal requires approval'; END IF;
 IF current_user<>'postgres' THEN RAISE EXCEPTION 'Reviewed owner required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='d1_migration_reader_20261022' AND rolcanlogin AND NOT rolinherit AND NOT rolsuper AND NOT rolcreatedb AND NOT rolcreaterole AND NOT rolreplication AND rolbypassrls AND rolconnlimit=3 AND rolvaliduntil='2026-11-05 10:00:00+00'::timestamptz) THEN RAISE EXCEPTION 'Reader boundary changed'; END IF;
 IF EXISTS(SELECT 1 FROM pg_auth_members WHERE member=(SELECT oid FROM pg_roles WHERE rolname='d1_migration_reader_20261022')) THEN RAISE EXCEPTION 'Reader memberships changed'; END IF;
 IF (SELECT obj_description(oid,'pg_namespace') FROM pg_namespace WHERE nspname='d1_migration') IS DISTINCT FROM 'pmrfp-d1-change-capture-v1; reviewed 2026-10-31' THEN RAISE EXCEPTION 'Private schema changed'; END IF;
 IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='d1_migration' AND p.proname IN ('capture_row','capture_truncate','acknowledge') AND p.proowner<>(SELECT oid FROM pg_roles WHERE rolname='postgres')) THEN RAISE EXCEPTION 'Queue owner changed'; END IF;
 IF ((SELECT jsonb_agg(jsonb_build_object('name',p.proname,'body',p.prosrc,'definer',p.prosecdef,'config',p.proconfig,'language',l.lanname,'args',pg_get_function_identity_arguments(p.oid),'returns',p.prorettype::regtype::text) ORDER BY p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='d1_migration' AND p.proname IN ('capture_row','capture_truncate','acknowledge'))='[{"args":"p_ids bigint[], p_destination_sha256 text","body":"\nDECLARE affected integer;\nBEGIN\n IF clock_timestamp()>=''2026-11-05 10:00:00+00''::timestamptz THEN RAISE EXCEPTION ''Change acknowledgement window expired''; END IF;\n IF p_ids IS NULL OR cardinality(p_ids)<1 OR cardinality(p_ids)>500 OR p_destination_sha256 IS NULL OR p_destination_sha256 !~ ''^[a-f0-9]{64}$'' OR\n EXISTS(SELECT 1 FROM unnest(p_ids) i WHERE i IS NULL OR i<1) OR\n (SELECT count(DISTINCT i) FROM unnest(p_ids) i)<>cardinality(p_ids) THEN RAISE EXCEPTION ''Invalid bounded acknowledgement''; END IF;\n IF (SELECT count(*) FROM d1_migration.outbox WHERE id=ANY(p_ids))<>cardinality(p_ids) THEN RAISE EXCEPTION ''Unknown acknowledgement IDs''; END IF;\n UPDATE d1_migration.outbox SET acknowledged_at=clock_timestamp(),destination_sha256=p_destination_sha256 WHERE id=ANY(p_ids) AND acknowledged_at IS NULL;\n GET DIAGNOSTICS affected=ROW_COUNT;\n RETURN affected;\nEND ","config":["search_path=pg_catalog"],"definer":true,"language":"plpgsql","name":"acknowledge","returns":"integer"},{"args":"","body":"\nDECLARE keys text[]; old_key jsonb; new_key jsonb;\nBEGIN\n IF pg_trigger_depth()=0 OR TG_TABLE_SCHEMA<>''public'' THEN RAISE EXCEPTION ''Trigger invocation required''; END IF;\n SELECT pk_columns INTO keys FROM d1_migration.registered_tables WHERE table_name=TG_TABLE_NAME;\n IF keys IS NULL THEN RAISE EXCEPTION ''Unregistered source table''; END IF;\n IF TG_OP=''UPDATE'' AND OLD IS NOT DISTINCT FROM NEW THEN RETURN NEW; END IF;\n IF TG_OP IN (''UPDATE'',''DELETE'') THEN\n  SELECT jsonb_object_agg(k,to_jsonb(OLD)->k) INTO old_key FROM unnest(keys) k;\n END IF;\n IF TG_OP IN (''UPDATE'',''INSERT'') THEN\n  SELECT jsonb_object_agg(k,to_jsonb(NEW)->k) INTO new_key FROM unnest(keys) k;\n END IF;\n IF TG_OP=''DELETE'' OR (TG_OP=''UPDATE'' AND old_key IS DISTINCT FROM new_key) THEN\n  INSERT INTO d1_migration.outbox(table_name,operation,key) VALUES(TG_TABLE_NAME,''delete'',old_key);\n END IF;\n IF TG_OP<>''DELETE'' THEN\n  INSERT INTO d1_migration.outbox(table_name,operation,key) VALUES(TG_TABLE_NAME,''upsert'',new_key);\n END IF;\n RETURN CASE WHEN TG_OP=''DELETE'' THEN OLD ELSE NEW END;\nEND ","config":["search_path=pg_catalog"],"definer":true,"language":"plpgsql","name":"capture_row","returns":"trigger"},{"args":"","body":"\nBEGIN\n IF pg_trigger_depth()=0 OR TG_TABLE_SCHEMA<>''public'' OR TG_OP<>''TRUNCATE'' THEN RAISE EXCEPTION ''Truncate trigger invocation required''; END IF;\n INSERT INTO d1_migration.outbox(table_name,operation,key) VALUES(TG_TABLE_NAME,''truncate'',''{}''::jsonb);\n RETURN NULL;\nEND ","config":["search_path=pg_catalog"],"definer":true,"language":"plpgsql","name":"capture_truncate","returns":"trigger"}]'::jsonb) IS DISTINCT FROM true THEN RAISE EXCEPTION 'Reviewed queue functions changed'; END IF;
 IF EXISTS(SELECT 1 FROM pg_tables WHERE schemaname='public' AND has_table_privilege('d1_migration_reader_20261022',format('%I.%I',schemaname,tablename),'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')) OR has_column_privilege('d1_migration_reader_20261022','auth.users','encrypted_password','SELECT') THEN RAISE EXCEPTION 'Reader permissions changed'; END IF;
 IF NOT has_function_privilege('d1_migration_reader_20261022','d1_migration.acknowledge(bigint[],text)','EXECUTE') OR NOT has_table_privilege('d1_migration_reader_20261022','d1_migration.auth_export_v1','SELECT') THEN RAISE EXCEPTION 'Existing scoped access missing'; END IF;
 IF EXISTS(SELECT 1 FROM pg_namespace n WHERE n.nspname='d1_migration' AND (has_schema_privilege('anon',n.oid,'USAGE') OR has_schema_privilege('authenticated',n.oid,'USAGE') OR has_schema_privilege('service_role',n.oid,'USAGE') OR EXISTS(SELECT 1 FROM aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE a.grantee=0))) THEN RAISE EXCEPTION 'Private schema exposed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='d1_migration.auth_export_v1'::regclass AND relkind='v' AND relowner=(SELECT oid FROM pg_roles WHERE rolname='postgres') AND 'security_barrier=true'=ANY(reloptions)) OR obj_description('d1_migration.auth_export_v1'::regclass,'pg_class') IS DISTINCT FROM 'pmrfp-sensitive-auth-export-v1; approved complete Supabase exit; expires 2026-11-05T10:00:00Z' THEN RAISE EXCEPTION 'Auth view boundary changed'; END IF;
 CREATE TEMP VIEW _d1_reviewed_auth_export_v1 WITH (security_barrier=true) AS  SELECT u.id,u.email,u.encrypted_password,u.email_confirmed_at,u.phone,
        u.phone_confirmed_at,u.created_at,u.updated_at,u.banned_until,u.deleted_at,
        u.is_anonymous,u.is_sso_user,u.raw_user_meta_data,u.raw_app_meta_data
 FROM auth.users u
 WHERE clock_timestamp() < '2026-11-05 10:00:00+00'::timestamptz;
 IF pg_get_viewdef('d1_migration.auth_export_v1'::regclass,true) IS DISTINCT FROM pg_get_viewdef('_d1_reviewed_auth_export_v1'::regclass,true) THEN RAISE EXCEPTION 'Auth view definition changed'; END IF;
 IF EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE c.oid='d1_migration.auth_export_v1'::regclass AND (a.grantee NOT IN ((SELECT oid FROM pg_roles WHERE rolname='postgres'),(SELECT oid FROM pg_roles WHERE rolname='d1_migration_reader_20261022')) OR (a.grantee=(SELECT oid FROM pg_roles WHERE rolname='d1_migration_reader_20261022') AND a.privilege_type<>'SELECT'))) THEN RAISE EXCEPTION 'Auth view ACL changed'; END IF;
 SELECT proacl,pg_get_functiondef(oid),prosrc INTO before_acl,definition,body FROM pg_proc WHERE oid='d1_migration.acknowledge(bigint[],text)'::regprocedure;
 IF (length(body)-length(replace(body,'2026-11-05 10:00:00+00','')))/length('2026-11-05 10:00:00+00')<>1 THEN RAISE EXCEPTION 'ACK expiry not uniquely identified'; END IF;
 EXECUTE replace(definition,'2026-11-05 10:00:00+00','2026-11-12 10:00:00+00');
 IF (SELECT proacl FROM pg_proc WHERE oid='d1_migration.acknowledge(bigint[],text)'::regprocedure) IS DISTINCT FROM before_acl THEN RAISE EXCEPTION 'ACK grants changed'; END IF;
 SELECT relacl INTO view_acl FROM pg_class WHERE oid='d1_migration.auth_export_v1'::regclass;
 definition:=pg_get_viewdef('d1_migration.auth_export_v1'::regclass,true);
 IF (length(definition)-length(replace(definition,'2026-11-05 10:00:00+00','')))/length('2026-11-05 10:00:00+00')<>1 OR position('clock_timestamp()' IN definition)=0 THEN RAISE EXCEPTION 'Auth expiry not uniquely identified'; END IF;
 EXECUTE 'CREATE OR REPLACE VIEW d1_migration.auth_export_v1 WITH (security_barrier=true) AS '||replace(definition,'2026-11-05 10:00:00+00','2026-11-12 10:00:00+00');
 IF (SELECT relacl FROM pg_class WHERE oid='d1_migration.auth_export_v1'::regclass) IS DISTINCT FROM view_acl THEN RAISE EXCEPTION 'Auth view grants changed'; END IF;
 EXECUTE 'ALTER ROLE d1_migration_reader_20261022 VALID UNTIL ''2026-11-12 10:00:00+00''';
END $renew$;
DROP VIEW _d1_reviewed_auth_export_v1;
COMMENT ON VIEW d1_migration.auth_export_v1 IS 'pmrfp-sensitive-auth-export-v1; approved complete Supabase exit; expires 2026-11-12T10:00:00Z';
COMMIT;
